/*getSysopIcomtrxlCaList*/ SELECT X.BUYER_ITEM_NO, --[00] X.UNIT_PRICE, --[01] X.LIST_PRICE, --[02] DECODE(X.UNIT_PRICE,0,0,ROUND(((X.UNIT_PRICE - X.LIST_PRICE)/X.UNIT_PRICE) *100,1)) AS RATE, --[03] X.DESCRIPTION, --[04] X.UNIT_MEASURE, --[05] X.PO_NO, --[06] X.AGENT_TEXT, --[07] X.SPECIFICATION, --[08] X.QTY, --[09] X.BUYER, --[10] X.AGENT AS AGENT, --[11] X.CONTRACT_NO, --[12] X.CONTRACT_SEQ, --[13] X.STATUS, --[14] X.DOC_NAME, --[15] X.TARGET, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.KEY_6 AND STATUS != 'D') AS BUYER_NAME, --[16] X.KEY_6, --[17] X.KEY_7, --[18] X.KEY_8, --[19] X.KEY_9, --[20] X.KEY_5, --[21] X.KEY_10, --[22] X.BELOW_COMORG_CODE , --[23] X.PROCESS_TYPE , --[24] X.ORIGIN_AGENT, --[25] X.IMPORT_FLAG, --[26] X.LOGISTICS_FEE, --[27] X.KEP_PRICE, --[28] X.CMS_CATLG_ID --[29]
,X.MARGIN_RE ,X.MARGIN_RE_TEXT ,X.AFTER_KEP_PRICE ,X.AFTER_UNIT_PRICE ,X.AFTER_LIST_PRICE ,DECODE(X.AFTER_UNIT_PRICE,0,0,ROUND(((X.AFTER_UNIT_PRICE - X.AFTER_LIST_PRICE)/X.AFTER_UNIT_PRICE) *100,1)) AS AFTER_RATE ,X.AFTER_AGENT ,X.AFTER_AGENT_TEXT ,CASE WHEN X.CONTRACT_NO IS NULL THEN '계약정보 없음' WHEN X.CONTRACT_SEQ IS NULL THEN '계약정보 없음' WHEN X.BUYER_ITEM_NO IS NULL THEN '품목정보 없음' WHEN X.AGENT_TEXT IS NULL THEN '협력사정보 없음' WHEN X.AFTER_AGENT_TEXT IS NULL THEN '협력사정보 없음'
WHEN X.UNIT_PRICE = X.AFTER_UNIT_PRICE OR X.AFTER_UNIT_PRICE = 0 THEN '매출가변경없음' WHEN X.LIST_PRICE = X.AFTER_LIST_PRICE OR X.AFTER_LIST_PRICE = 0 THEN '매입가변경없음' WHEN X.ITEM_MAKE_TYPE = X.AFTER_ITEM_MAKE_TYPE THEN '품목구분변경없음' WHEN X.DELIVERY_LT = X.AFTER_DELIVERY_LT THEN '표준납기일변경없음' ELSE '정상' END CHECK_STATUS_TEXT , X.ITEM_MAKE_TYPE , X.DELIVERY_LT , X.AFTER_ITEM_MAKE_TYPE , X.AFTER_DELIVERY_LT, X.RE_MIN_ORDER_QTY, X.CH_MIN_ORDER_QTY, X.RE_PUR_UNIT_QTY, X.CH_PUR_UNIT_QTY, X.RE_SELLER_AREA, X.CH_SELLER_AREA, X.RE_PROCESS_TYPE, X.CH_PROCESS_TYPE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND FLAG = 'Y' AND CODE = X.RE_PROCESS_TYPE) AS RE_PROCESS_TYPE_TEXT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND FLAG = 'Y' AND CODE = X.CH_PROCESS_TYPE) AS CH_PROCESS_TYPE_TEXT, X.RE_ORIGIN_AGENT AS RE_WAREHOUSE_CODE, X.CH_ORIGIN_AGENT AS CH_WAREHOUSE_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.RE_ORIGIN_AGENT) AS RE_WAREHOUSE_CODE_TEXT, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.CH_ORIGIN_AGENT) AS CH_WAREHOUSE_CODE_TEXT, DECODE(X.CH_SELLER_AREA,'','4','5') AS SELLER_AREA_IMG, /*SLOGIC-BEGIN(P04-4041-01)*/ DECODE((SELECT COUNT(*) FROM BNTSLGIMP WHERE SLG_ID = 'P04-4041-01' AND COM_CODE = X.BELOW_COMORG_CODE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN OPEN_DATE AND CLOSE_DATE), 0, 'N', 'Y') AS MOQ_USE_FLAG, /*SLOGIC-END*/ /*SLOGIC-BEGIN(P04-4041-02)*/ DECODE((SELECT COUNT(*) FROM BNTSLGIMP WHERE SLG_ID = 'P04-4041-02' AND COM_CODE = X.BELOW_COMORG_CODE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN OPEN_DATE AND CLOSE_DATE), 0, 'N', 'Y') AS AREA_USE_FLAG, /*SLOGIC-END*/ X.CH_SELL_CLOSE_DATE, X.RE_SELL_CLOSE_DATE, X.CH_BUY_CLOSE_DATE, X.RE_BUY_CLOSE_DATE, X.UNIT_PRICE_CHANGE_REASON, X.LIST_PRICE_CHANGE_REASON FROM ( SELECT B.BUYER_ITEM_NO, B.UNIT_PRICE, B.LIST_PRICE AS LIST_PRICE, B.DESCRIPTION, B.UNIT_MEASURE, ' ' AS PO_NO, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.AGENT) AS AGENT_TEXT, B.SPECIFICATION, 0 AS QTY, B.BUYER, B.AGENT AS AGENT, B.CONTRACT_NO, B.CONTRACT_SEQ, DECODE(C.STATUS,'D','D',DECODE(B.STATUS,'D','D',DECODE(C.PRODUCT_CLOSE_FLAG,'N','N','Y','Y','T','Y'))) AS STATUS, A.DOC_NAME, A.TARGET, A.KEY_6, A.KEY_7, A.KEY_8, A.KEY_9, A.KEY_5, A.KEY_10, B.BELOW_COMORG_CODE , B.PROCESS_TYPE , B.ORIGIN_AGENT, B.IMPORT_FLAG, B.LOGISTICS_FEE, B.KEP_PRICE, C.CMS_CATLG_ID ,'' MARGIN_RE ,'' MARGIN_RE_TEXT ,NVL(B.KEP_PRICE,0) AFTER_KEP_PRICE ,DECODE(A.KEY_14,' ',B.UNIT_PRICE, A.KEY_14) AFTER_UNIT_PRICE ,DECODE(A.KEY_13,' ',B.LIST_PRICE, A.KEY_13) AFTER_LIST_PRICE ,0 AFTER_RATE ,NVL(A.KEY_12,'') AFTER_AGENT , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.KEY_12 AND BUSINESS_COND = 'S' AND STATUS IN ('C','R')) AS AFTER_AGENT_TEXT , B.ITEM_MAKE_TYPE , B.DELIVERY_LT , NVL(A.KEY_17, B.ITEM_MAKE_TYPE) AS AFTER_ITEM_MAKE_TYPE , NVL(A.KEY_19, B.DELIVERY_LT) AS AFTER_DELIVERY_LT , NVL(A.KEY_20, B.SELL_CLOSE_DATE) AS CH_SELL_CLOSE_DATE , B.SELL_CLOSE_DATE AS RE_SELL_CLOSE_DATE , B.MIN_ORDER_QTY AS RE_MIN_ORDER_QTY , NVL(A.KEY_21, B.MIN_ORDER_QTY) AS CH_MIN_ORDER_QTY , B.PUR_UNIT_QTY AS RE_PUR_UNIT_QTY , NVL(A.KEY_22, B.PUR_UNIT_QTY) AS CH_PUR_UNIT_QTY , B.SELLER_AREA AS RE_SELLER_AREA , NVL(A.KEY_23, B.SELLER_AREA) AS CH_SELLER_AREA , B.PROCESS_TYPE AS RE_PROCESS_TYPE , DECODE(A.KEY_15,' ',B.PROCESS_TYPE,A.KEY_15) AS CH_PROCESS_TYPE , B.ORIGIN_AGENT AS RE_ORIGIN_AGENT , DECODE(A.KEY_16,' ', DECODE(A.KEY_15, '0', '', B.ORIGIN_AGENT) ,A.KEY_16) AS CH_ORIGIN_AGENT , NVL(A.KEY_24, B.BUY_CLOSE_DATE) AS CH_BUY_CLOSE_DATE , B.BUY_CLOSE_DATE AS RE_BUY_CLOSE_DATE , NVL(A.KEY_25, '') AS UNIT_PRICE_CHANGE_REASON , NVL(A.KEY_26, '') AS LIST_PRICE_CHANGE_REASON FROM BNTTRXL A, ICOMCQDT B, ICOMBYIT C WHERE A.DOC_NAME = 'KEPMGPDT'
AND A.KEY_6 = #{st_buyer_code}
AND A.KEY_7 = #{st_user_id} AND A.KEY_8 = #{trxl_gubun} AND A.TARGET = B.BUYER(+) AND A.KEY_1 = B.BUYER_ITEM_NO(+) AND A.KEY_2 = B.AGENT(+) AND A.KEY_3 = B.CONTRACT_NO(+) AND A.KEY_4 = B.CONTRACT_SEQ(+) AND B.BUYER = C.BUYER(+) AND B.BUYER_ITEM_NO = C.BUYER_ITEM_NO(+) )X ORDER BY X.BUYER,X.BUYER_ITEM_NO

mapper.update:
